#include <iostream>
using namespace std;

int main() {
    int j, m, k;
    cin >> j >> m >> k;
    int sekarang = j * 60 + m;
    int dulu = (sekarang - k % 1440 + 1440) % 1440;
    cout << dulu / 60 << " " << dulu % 60 << endl;
    return 0;
}

#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    int a, b, c;
    cin >> a >> b >> c;
    int besarAB = (a + b + abs(a - b)) / 2;
    int kecilAB = (a + b - abs(a - b)) / 2;
    int terbesar = (besarAB + c + abs(besarAB - c)) / 2;
    int terkecil = (kecilAB + c - abs(kecilAB - c)) / 2;
    cout << a + b + c - terbesar - terkecil << endl;
    return 0;
}

